package com.cryptostrategy.platform.evaluation.internal;import com.cryptostrategy.platform.evaluation.api.model.*;import java.util.*;public final class EvaluationReproductionVerifier{public EvaluationVerificationReport verify(EvaluationResult a,EvaluationResult b){List<String>d=new ArrayList<>();if(a.totalReturn().compareTo(b.totalReturn())!=0)d.add("totalReturn");if(a.winRate().compareTo(b.winRate())!=0)d.add("winRate");if(a.maximumDrawdown().compareTo(b.maximumDrawdown())!=0)d.add("maximumDrawdown");if(a.numberOfTrades()!=b.numberOfTrades())d.add("numberOfTrades");if(a.overallScore().compareTo(b.overallScore())!=0)d.add("overallScore");if(!a.fingerprint().equals(b.fingerprint()))d.add("evaluationFingerprint");return new EvaluationVerificationReport(d.isEmpty(),d);}}
